curl -s -A "Mozilla/5.0" "https://developer.apple.com/tutorials/data/design/human-interface-guidelines/voiceover.json" -o /tmp/vo.json; python3 - <<'EOF'
import json,re
d=json.load(open('/tmp/vo.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text': out.append(o['text'])
        elif o.get('type')=='heading': out.append('\n## '+o.get('text','')+'\n')
        elif o.get('type')=='paragraph':
            out.append('\n')
            for c in o.get('inlineContent',[]): walk(c,out)
            out.append('\n')
        else:
            for k,v in o.items(): walk(v,out)
    elif isinstance(o,list):
        for i in o: walk(i,out)
txt=[]
walk(d.get('primaryContentSections',d),txt)
s=''.join(txt)
s=re.sub(r'\n{3,}','\n\n',s)
print(s[:9000])
EOF
